// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import type { Fact, WalkStep } from '@/app/demos/stage/types'

const DATA = [
  { id: 1, name: 'Ada', role: 'admin' },
  { id: 2, name: 'Linus', role: 'dev' },
]

type Row = (typeof DATA)[number]
const KEYS = Object.keys(DATA[0]) as (keyof Row)[]

export const JSON_LINES = JSON.stringify(DATA, null, 2).split('\n')

/** Same shapes the extension's converters produce for an array of flat objects. */
export const OUTPUTS = [
  {
    format: 'CSV',
    lines: [KEYS.join(','), ...DATA.map((row) => KEYS.map((key) => row[key]).join(','))],
  },
  {
    format: 'XML',
    lines: [
      '<?xml version="1.0" encoding="UTF-8"?>',
      ...DATA.flatMap((row) => [
        '<item>',
        ...KEYS.map((key) => `  <${key}>${row[key]}</${key}>`),
        '</item>',
      ]),
    ],
  },
  {
    format: 'YAML',
    lines: DATA.flatMap((row) =>
      KEYS.map((key, index) => `${index === 0 ? '- ' : '  '}${key}: ${row[key]}`),
    ),
  },
  {
    format: 'MARKDOWN',
    lines: [
      `| ${KEYS.join(' | ')} |`,
      `| ${KEYS.map(() => '---').join(' | ')} |`,
      ...DATA.map((row) => `| ${KEYS.map((key) => row[key]).join(' | ')} |`),
    ],
  },
]

/** Same list as `FORMATS` in `src/tools/data/universal-converter/Tool.tsx`. */
export const FORMATS = ['JSON', 'CSV', 'XML', 'YAML', 'MARKDOWN', 'TSV'] as const

/** Markdown cannot be parsed as input (`Tool.tsx` convert throws). */
export const INPUT_FORMATS = ['JSON', 'CSV', 'TSV', 'XML', 'YAML'] as const

